/**
 * Minimal label store for the component library.
 *
 * Components call `t("key")` / `tf("key", ...args)` synchronously, so the
 * dictionary is a module-level object. The base dictionary is picked from
 * `navigator.language` (zh -> Chinese, otherwise English) at module load, and
 * hosts can still override any copy via the `<AgentChat labels={...}>` /
 * `<CopilotApp labels={...}>` prop, which calls `setLabels` at mount.
 *
 * `tf` formats positional placeholders `{0} {1}` in declaration order.
 */

export type Labels = Record<string, string>

