function detectBase(): Labels {
  try {
    if (typeof navigator !== 'undefined') {
      const lang = (navigator.language || '').toLowerCase()
      if (lang.startsWith('zh')) return ZH
    }
  } catch {
    /* ignore: non-browser env */
  }
  return EN
}

let base: Labels = detectBase()
let overridesMem: Labels | undefined
let current: Labels = { ...base }

export function setLabels(overrides?: Labels): void {
  overridesMem = overrides
  current = overrides ? { ...base, ...overrides } : { ...base }
}

/**
 * Force the base locale from a config/meta hint (`'zh'` / `'en'`); anything else
 * (e.g. `'auto'`) falls back to browser auto-detection. Re-applies any active
 * `setLabels` overrides on top.
 */
export function setLanguage(lang?: string): void {
  const l = (lang || '').toLowerCase()
  if (l.startsWith('zh')) base = ZH
  else if (l.startsWith('en')) base = EN
  else base = detectBase()
  current = { ...base, ...(overridesMem ?? {}) }
}

export function t(key: string): string {
  return current[key] ?? key
}

export function tf(key: string, ...args: (string | number)[]): string {
  const tpl = current[key] ?? key
  return tpl.replace(/\{(\d+)\}/g, (_m, i) => {
    const v = args[Number(i)]
    return v == null ? '' : String(v)
  })
}
